package com.payments.gateway

import java.net.HttpURLConnection
import java.net.URL
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class PaymentRequest(
    val merchantId: String,
    val amount: Long,
    val currency: String,
    val customerRef: String,
    val idempotencyKey: String
)

data class RateLimitEntry(
    val count: AtomicInteger = AtomicInteger(0),
    val windowStart: Long = System.currentTimeMillis()
)

class PaymentGateway(
    private val upstreamUrl: String,
    private val hmacSecret: String,
    private val maxRetries: Int = 3,
    private val rateLimit: Int = 100
) {
    private val rateLimitMap = ConcurrentHashMap<String, RateLimitEntry>()
    private val processedKeys = ConcurrentHashMap<String, Int>()

    fun checkRateLimit(merchantId: String): Boolean {
        val entry = rateLimitMap.computeIfAbsent(merchantId) { RateLimitEntry() }
        val now = System.currentTimeMillis()
        if (now - entry.windowStart > 60_000) {
            rateLimitMap[merchantId] = RateLimitEntry()
            return true
        }
        return entry.count.incrementAndGet() <= rateLimit
    }

    fun computeHmac(payload: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(hmacSecret.toByteArray(), "HmacSHA256"))
        return mac.doFinal(payload.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    fun sanitizeMerchantId(input: String): String {
        return input.replace(Regex("[^a-zA-Z0-9_-]"), "")
    }

    fun sanitizeCurrency(input: String): String {
        // ISO-4217 currency codes are exactly 3 uppercase letters.
        // Reject anything that does not match to prevent JSON injection.
        require(input.matches(Regex("[A-Z]{3}"))) { "Invalid currency code" }
        return input
    }

    fun encodeHeaderValue(value: String): String {
        // Encode for safe header inclusion - strip control chars
        return value.filter { it.code >= 0x20 && it.code != 0x7F }
    }

    fun buildLogCorrelationId(request: PaymentRequest): String {
        val raw = "${request.merchantId}:${request.idempotencyKey}:${request.amount}"
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(raw.toByteArray()).take(8).joinToString("") { "%02x".format(it) }
    }

    fun formatCustomerReference(ref: String): String {
        // Customer references may contain locale-specific formatting
        // We normalize Unicode but preserve the semantic content
        val normalized = java.text.Normalizer.normalize(ref, java.text.Normalizer.Form.NFC)
        return normalized.take(128)
    }

    fun processPayment(request: PaymentRequest): Result<Int> {
        val safeMerchantId = sanitizeMerchantId(request.merchantId)

        val safeCurrency = try {
            sanitizeCurrency(request.currency)
        } catch (e: IllegalArgumentException) {
            return Result.failure(e)
        }

        if (!checkRateLimit(safeMerchantId)) {
            return Result.failure(RuntimeException("Rate limit exceeded"))
        }

        // Idempotency check
        processedKeys[request.idempotencyKey]?.let {
            return Result.success(it)
        }

        val correlationId = buildLogCorrelationId(request)
        val customerRef = formatCustomerReference(request.customerRef)

        return executeWithRetry(safeMerchantId, request.amount, safeCurrency, customerRef, correlationId, request.idempotencyKey)
    }

    private fun executeWithRetry(
        merchantId: String,
        amount: Long,
        currency: String,
        customerRef: String,
        correlationId: String,
        idempotencyKey: String
    ): Result<Int> {
        var lastException: Exception? = null

        for (attempt in 1..maxRetries) {
            try {
                val responseCode = sendUpstreamRequest(merchantId, amount, currency, customerRef, correlationId, idempotencyKey)
                if (responseCode in 200..299) {
                    processedKeys[idempotencyKey] = responseCode
                    return Result.success(responseCode)
                }
                if (responseCode in 400..499) {
                    return Result.failure(RuntimeException("Client error: $responseCode"))
                }
                // 5xx - retry
                lastException = RuntimeException("Server error: $responseCode")
            } catch (e: Exception) {
                lastException = e
            }
            Thread.sleep(attempt * 1000L)
        }
        return Result.failure(lastException ?: RuntimeException("Unknown error"))
    }

    private fun sendUpstreamRequest(
        merchantId: String,
        amount: Long,
        currency: String,
        customerRef: String,
        correlationId: String,
        idempotencyKey: String
    ): Int {
        val payload = "{\"merchant\":\"$merchantId\",\"amount\":$amount,\"currency\":\"$currency\"}"
        val signature = computeHmac(payload)

        val conn = URL(upstreamUrl).openConnection() as HttpURLConnection
        conn.requestMethod = "POST"
        conn.setRequestProperty("Content-Type", "application/json")
        conn.setRequestProperty("X-Signature", signature)
        conn.setRequestProperty("X-Correlation-Id", correlationId)
        conn.setRequestProperty("X-Idempotency-Key", encodeHeaderValue(idempotencyKey))
        conn.setRequestProperty("X-Customer-Ref", encodeHeaderValue(customerRef))
        conn.setRequestProperty("X-Merchant-Id", merchantId)
        conn.doOutput = true

        conn.outputStream.use { it.write(payload.toByteArray()) }
        return conn.responseCode
    }
}
